package io.github.rebrowser.ui;
import static org.junit.Assert.*;
import java.lang.reflect.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.Test;
/** Flat favorites UI/frame model; no store/Android/navigation effect. */
public final class BookmarkViewTest {
 private static BookmarkView.Row row(Object token,String title){return new BookmarkView.Row(token,title,"https://example.test/");}
 private static List<BookmarkView.Row> page(int count){List<BookmarkView.Row> rows=new ArrayList<>();for(int i=0;i<count;i++)rows.add(row(new Object(),"收藏"+i));return rows;}
 @Test public void labelAndAddressAreNotFoldersOrEnvironmentBookmarks(){BookmarkView.Row row=row(new Object(),"网址");assertEquals("网址",BookmarkView.Rows.label(row));assertEquals("https://example.test/",BookmarkView.Rows.description(row));assertEquals(0,Arrays.stream(BookmarkView.class.getDeclaredClasses()).filter(c->c.getSimpleName().equals("Tree") || c.getSimpleName().equals("Node")).count());}
 @Test public void boundsAndMalformedTextReject(){Object token=new Object();assertThrows(IllegalArgumentException.class,()->new BookmarkView.Row(null,"t","u"));assertThrows(IllegalArgumentException.class,()->new BookmarkView.Row(token,"","u"));assertThrows(IllegalArgumentException.class,()->new BookmarkView.Row(token,"t",""));assertThrows(IllegalArgumentException.class,()->new BookmarkView.Row(token,"x".repeat(641),"u"));assertThrows(IllegalArgumentException.class,()->new BookmarkView.Row(token,"t","u".repeat(8193)));for(String invalid:new String[]{"\ud800","\udc00","line\nbreak","nul\u0000"})assertThrows(IllegalArgumentException.class,()->new BookmarkView.Row(token,invalid,"u"));assertEquals("标题😀",row(token,"标题😀").title());}
 @Test public void exactListBudgetAndRevisionDoNotTruncate(){BookmarkView.State state=new BookmarkView.State();assertNotNull(state.show(1,page(BookmarkView.MAX_ROWS)));assertEquals(BookmarkView.MAX_ROWS,state.rowCount());assertThrows(IllegalArgumentException.class,()->state.show(2,page(BookmarkView.MAX_ROWS+1)));assertThrows(IllegalArgumentException.class,()->state.show(0,page(1)));assertEquals(BookmarkView.MAX_ROWS,state.rowCount());}
 @Test public void duplicateIdentityOrNullRejectedNotGuessed(){Object token=new Object();BookmarkView.State state=new BookmarkView.State();assertThrows(IllegalArgumentException.class,()->state.show(1,Arrays.asList(row(token,"a"),row(token,"b"))));assertThrows(IllegalArgumentException.class,()->state.show(1,Arrays.asList(row(token,"a"),null)));}
 @Test public void defensiveImmutableRows(){BookmarkView.State state=new BookmarkView.State();List<BookmarkView.Row> input=page(2);BookmarkView.Row first=input.get(0);Object frame=state.show(5,input);input.clear();assertEquals(2,state.rowCount());assertSame(first,state.require(frame,5,first.itemRef()));assertThrows(UnsupportedOperationException.class,()->state.rows().clear());}
 @Test public void oldFrameCannotRetargetNewFavorite(){BookmarkView.State state=new BookmarkView.State();BookmarkView.Row old=row(new Object(),"old"),next=row(new Object(),"new");Object frame=state.show(1,Arrays.asList(old));state.show(2,Arrays.asList(next));assertFalse(state.current(frame,1));assertThrows(IllegalStateException.class,()->state.require(frame,1,old.itemRef()));assertSame(next,state.require(state.frame(),2,next.itemRef()));}
 @Test public void wrongRevisionTokenAndBoundsReject(){BookmarkView.State state=new BookmarkView.State();BookmarkView.Row row=row(new Object(),"x");Object frame=state.show(3,Arrays.asList(row));assertThrows(IllegalStateException.class,()->state.require(frame,4,row.itemRef()));assertThrows(IllegalArgumentException.class,()->state.require(frame,3,new Object()));assertNull(state.rowAt(-1));assertNull(state.rowAt(1));}
 @Test public void hideDropsPrivateRowsAndAllowsExplicitRebind(){BookmarkView.State state=new BookmarkView.State();Object frame=state.show(1,page(2));state.hide();assertTrue(state.rows().isEmpty());assertFalse(state.current(frame,1));state.show(2,page(1));assertEquals(1,state.rowCount());}
 @Test public void retirementOneWay(){BookmarkView.State state=new BookmarkView.State();state.show(1,page(1));state.retire();state.retire();assertEquals(0,state.rowCount());assertThrows(IllegalStateException.class,()->state.show(2,page(1)));}
 @Test public void foreignThreadCannotUseRows()throws Exception{BookmarkView.State state=new BookmarkView.State();state.show(1,page(1));ExecutorService worker=Executors.newSingleThreadExecutor();try{assertTrue(worker.submit(()->{try{state.rows();return false;}catch(IllegalStateException expected){return true;}}).get(3,TimeUnit.SECONDS));}finally{worker.shutdown();assertTrue(worker.awaitTermination(3,TimeUnit.SECONDS));}}
 @Test public void resolvingMetadataTokenDoesNotMutateAnything(){BookmarkView.State state=new BookmarkView.State();List<BookmarkView.Row> rows=page(2);Object frame=state.show(1,rows);assertSame(rows.get(0),state.require(frame,1,rows.get(0).itemRef()));assertEquals(2,state.rowCount());assertEquals(1,state.revision());}
 @Test public void viewHasNoStoreOrFolderManagement(){for(Method method:BookmarkView.class.getDeclaredMethods())for(String word:new String[]{"persist","dialog","authorize","trust","folder"})assertFalse(method.getName().toLowerCase().contains(word));assertEquals(4,BookmarkView.Actions.class.getDeclaredMethods().length);for(Method method:BookmarkView.Actions.class.getDeclaredMethods()){assertTrue(Modifier.isAbstract(method.getModifiers()));assertEquals(method.getName().equals("add")?1:2,method.getParameterCount());}}
}
